<script setup lang="ts">
const {state,send}=usePortal();if(state.value?.user?.role!=='admin')await navigateTo('/');
const overview=ref<any>(null),error=ref(''),message=ref(''),busy=ref(false),invite=ref(''),plexId=ref(''),jellyfinId=ref(''),selected=ref<any>(null),libraries=ref<string[]>([]),recoverId=ref(''),confirmDisable=ref(false),catalog=ref<any>(null);
const catalogBusy=ref(false),catalogError=ref(''),removeMapping=ref('');
const plexLibraries=computed(()=>{const items=new Map<string,{id:string;name:string}>();for(const share of catalog.value?.plex||[])for(const l of share.libraries||[]){if(l.id!=null){const id=String(l.id);items.set(id,{id,name:l.title||'Library '+id});}}return [...items.values()];});
function libraryName(service:string,id:string){return (service==='plex'?plexLibraries.value:catalog.value?.jellyfin||[]).find((l:any)=>String(l.id)===String(id))?.name||'Unavailable library ('+id+')';}
async function loadCatalog(){catalogBusy.value=true;catalogError.value='';try{catalog.value=await requestFetch('/api/admin/libraries');}catch(e){catalogError.value=errorText(e);}finally{catalogBusy.value=false;}}
const requestFetch=useRequestFetch();
async function load(){overview.value=await requestFetch('/api/admin/overview');}
if(state.value?.user?.role==='admin')try{await load();await loadCatalog();}catch(e){error.value=errorText(e);}
async function run(fn:()=>Promise<any>,success='Saved.'){busy.value=true;error.value='';message.value='';try{await fn();await load();message.value=success;}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function action(action:string){if(!selected.value)return;await run(()=>send('admin/user',{userId:selected.value.id,action,libraries:[...libraries.value],...(recoverId.value?{jellyfinId:recoverId.value}:{})}));selected.value=overview.value?.users.find((u:any)=>u.id===selected.value.id);confirmDisable.value=false;}
function select(user:any){error.value='';message.value='';selected.value=user;libraries.value=JSON.parse(user.libraries).map(String);recoverId.value='';confirmDisable.value=false;}
const jellyfinLibraries=computed<{id:string;name:string}[]>(()=>[
 ...(catalog.value?.jellyfin||[]).map((library:any)=>({id:String(library.id),name:library.name})),
 ...libraries.value.filter(id=>!(catalog.value?.jellyfin||[]).some((library:any)=>String(library.id)===id)).map(id=>({id,name:'Unavailable library ('+id+')'}))
]);
const librariesDirty=computed(()=>{const saved:string[]=JSON.parse(selected.value?.libraries||'[]').map(String);return saved.length!==libraries.value.length||libraries.value.some(id=>!saved.includes(id));});
function selectLibrary(id:string,checked:boolean){libraries.value=checked?[...new Set([...libraries.value,id])]:libraries.value.filter(value=>value!==id);}
const date=(value:number)=>new Date(value).toLocaleString();
</script>
<template><main v-if="overview" class="page admin-page"><div class="page-title"><h1>Admin</h1></div><CindorAlert v-if="error" class="portal-alert" tone="danger">{{error}}</CindorAlert><div v-if="message" class="notice" role="status">{{message}}</div>
  <nav class="actions admin-communications" aria-label="Admin tools"><NuxtLink class="button" to="/admin/status">Service status</NuxtLink><NuxtLink class="button" to="/admin/alerts">Email alerts</NuxtLink><NuxtLink class="button" to="/admin/news">Manage news</NuxtLink></nav>
  <section class="health-strip" aria-label="Integration configuration"><span v-for="(ready,name) in overview.health" :key="name"><span class="status-dot" :class="{offline:!ready}"/>{{name}} · {{ready?'Configured':'Needs configuration'}}</span></section><p class="small muted">Configuration status only; live connections are not checked.</p>
  <div class="settings-grid admin-grid"><section class="panel"><h2>Invite someone</h2><form @submit.prevent="run(async()=>{await send('admin/invite',{email:invite});invite='';},'Invitation queued for delivery.')"><label for="invite">Email address</label><CindorInput id="invite" v-model="invite" type="email" required/><CindorButton type="submit" variant="solid" class="button primary" :disabled="busy">Send invitation</CindorButton></form><ul class="plain-list"><li v-for="i in overview.invites" :key="i.email"><span>{{i.email}}<small>Expires {{date(i.expires)}}</small></span><CindorButton variant="ghost" class="text-button" :disabled="busy" @click="run(()=>send('admin/invite/revoke',{email:i.email}))">Revoke</CindorButton></li></ul></section>
  <section class="panel"><div class="section-heading"><h2>Library mapping</h2><CindorButton variant="ghost" class="text-button" :disabled="catalogBusy||busy" @click="loadCatalog">{{catalogBusy?'Loading…':'Refresh libraries'}}</CindorButton></div><p>Match Plex libraries to Jellyfin.</p><CindorAlert v-if="catalogError" class="portal-alert" tone="danger">{{catalogError}}</CindorAlert><p v-if="catalogBusy" role="status">Loading libraries…</p><form v-if="catalog" @submit.prevent="run(async()=>{await send('admin/mapping',{plexId,jellyfinId});plexId='';jellyfinId='';},'Mapping saved.')"><div class="field-pair"><div><label for="plex-library">Plex library</label><CindorSelect id="plex-library" v-model="plexId" :value.attr="plexId" required :disabled="busy||catalogBusy"><option value="" disabled>Choose a library</option><option v-for="l in plexLibraries" :key="l.id" :value="l.id">{{l.name}}</option></CindorSelect></div><div><label for="jellyfin-library">Jellyfin library</label><CindorSelect id="jellyfin-library" v-model="jellyfinId" :value.attr="jellyfinId" required :disabled="busy||catalogBusy"><option value="" disabled>Choose a library</option><option v-for="l in catalog.jellyfin" :key="l.id" :value="String(l.id)">{{l.name}}</option></CindorSelect></div></div><p v-if="!plexLibraries.length||!catalog.jellyfin.length" class="small">No libraries found. Check integration and sharing settings, then refresh.</p><CindorButton type="submit" variant="ghost" class="button" :disabled="busy||catalogBusy||!plexId||!jellyfinId">Save mapping</CindorButton></form><ul class="plain-list"><li v-for="m in overview.mappings" :key="m.plex_id"><div><strong>{{libraryName('plex',m.plex_id)}}</strong><small>→ {{libraryName('jellyfin',m.jellyfin_id)}}</small><div v-if="removeMapping===m.plex_id"><p class="small">Remove this mapping? Linked access will be reviewed.</p><CindorButton variant="ghost" class="text-button" :disabled="busy" @click="run(async()=>{await send('admin/mapping/remove',{plexId:m.plex_id});removeMapping='';},'Mapping removed.')">Confirm removal</CindorButton><CindorButton variant="ghost" class="text-button" :disabled="busy" @click="removeMapping=''">Cancel</CindorButton></div></div><div><CindorButton variant="ghost" class="text-button" :disabled="busy||!catalog" @click="plexId=String(m.plex_id);jellyfinId=String(m.jellyfin_id)">Edit</CindorButton><CindorButton variant="ghost" class="text-button" :disabled="busy" @click="removeMapping=m.plex_id">Remove</CindorButton></div></li></ul><p v-if="!overview.mappings.length" class="small">No libraries mapped yet.</p></section></div>
  <PlexAdmin/><section class="panel people"><h2>People <span class="count">{{overview.users.length}}</span></h2><div class="table-scroll"><table><thead><tr><th>Person</th><th>Jellyfin</th><th>Live TV</th><th>Account</th><th><span class="sr-only">Manage</span></th></tr></thead><tbody><tr v-for="u in overview.users" :key="u.id"><td><strong>{{u.name}}</strong><small>{{u.email||'Plex sign-in'}}</small></td><td>{{u.jellyfin_state}}</td><td>{{u.iptv}}</td><td>{{u.disabled?'Disabled':u.role==='admin'?'Administrator':'Active'}}</td><td><CindorButton variant="ghost" class="text-button" :disabled="busy" @click="select(u)">Manage</CindorButton></td></tr></tbody></table></div></section>
  <section v-if="selected" class="panel person-detail" aria-labelledby="person-title" :aria-busy="busy">
   <div class="section-heading"><div><p class="eyebrow">MANAGE PERSON</p><h2 id="person-title">{{selected.name}}</h2><p class="small">{{selected.email||'Plex sign-in'}} · {{selected.disabled?'Account disabled':selected.role==='admin'?'Administrator':'Active account'}}</p></div><CindorButton variant="ghost" class="text-button" :disabled="busy" @click="selected=null">Close</CindorButton></div>
   <CindorAlert v-if="error" class="portal-alert" tone="danger">{{error}}</CindorAlert><p v-if="message" class="notice" role="status">{{message}}</p>
   <div class="person-access-grid">
    <section class="person-section" aria-labelledby="jellyfin-access-title">
     <h3 id="jellyfin-access-title">Jellyfin access</h3>
     <p class="small">{{selected.policy_source==='manual'?'Independent access is active. Choose which libraries this person can watch.':selected.policy_source==='plex'?'Access follows their Plex libraries through your library mappings. Choose libraries below to set independent access.':selected.disabled?'Access is blocked while this account is disabled.':'Jellyfin access is blocked. Save a library selection or use Plex access to restore it.'}}</p>
     <p v-if="catalogBusy" class="small" role="status">Loading libraries…</p>
     <div v-if="catalogError" class="notice" role="alert"><p>Could not load libraries: {{catalogError}}</p><CindorButton variant="ghost" class="text-button" :disabled="busy||catalogBusy" @click="loadCatalog">Retry loading libraries</CindorButton></div>
     <fieldset v-if="catalog" :disabled="busy||catalogBusy||!!selected.disabled" class="person-library-picker"><legend>Libraries available to this person</legend><div class="person-library-options"><CindorCheckbox v-for="library in jellyfinLibraries" :key="library.id" class="check-label" :model-value="libraries.includes(library.id)" :disabled="busy||catalogBusy||!!selected.disabled" @update:model-value="selectLibrary(library.id,$event)">{{library.name}}</CindorCheckbox></div><p v-if="!jellyfinLibraries.length" class="small muted">No Jellyfin libraries found. Add libraries in Jellyfin, then refresh the library list above.</p></fieldset>
     <p v-if="catalog&&!libraries.length" class="small muted">No libraries selected. Saving independent access removes access to all Jellyfin libraries.</p>
     <div class="actions"><CindorButton variant="solid" class="button primary" :disabled="busy||catalogBusy||!catalog||!!catalogError||!!selected.disabled||(selected.policy_source==='manual'&&!librariesDirty)" @click="action('manual-libraries')">Save library access</CindorButton><CindorButton v-if="selected.policy_source!=='plex'" variant="ghost" class="text-button" :disabled="busy||!!selected.disabled" @click="action('plex-libraries')">Use Plex access</CindorButton><span v-if="librariesDirty" class="small muted">Unsaved changes</span></div>
    </section>
    <section class="person-section" aria-labelledby="live-tv-title"><h3 id="live-tv-title">Live TV</h3><p class="small">{{selected.iptv==='approved'?'Live TV is enabled. This person can watch Live TV.':selected.iptv==='pending'?'This person can enable Live TV immediately.':selected.iptv==='revoked'?'Access was revoked. Only an administrator can restore it.':'This person can enable Live TV from their account.'}}</p><div class="actions"><CindorButton v-if="selected.iptv!=='approved'" variant="ghost" class="button" :disabled="busy||!!selected.disabled" @click="action('approve-iptv')">{{selected.iptv==='revoked'?'Restore Live TV':'Enable Live TV'}}</CindorButton><CindorButton v-else variant="ghost" class="button" :disabled="busy" @click="action('revoke-iptv')">Revoke Live TV</CindorButton></div></section>
   </div>
   <section v-if="['creating','needs-review'].includes(selected.jellyfin_state)" class="person-section person-recovery" aria-labelledby="recovery-title"><h3 id="recovery-title">Jellyfin setup needs attention</h3><form @submit.prevent="action('retry-jellyfin')"><p class="small">Check Jellyfin for the interrupted account named {{selected.jellyfin_name}}. Confirm its ID before linking; administrator accounts cannot be used.</p><label for="recover">Confirmed Jellyfin user ID</label><CindorInput id="recover" v-model="recoverId" :disabled="busy" required/><CindorButton type="submit" variant="ghost" class="button" :disabled="busy||!recoverId.trim()">Link Jellyfin account</CindorButton></form></section>
   <section class="person-section person-account" aria-labelledby="account-status-title"><div><h3 id="account-status-title">Account status</h3><p class="small">{{selected.disabled?'This account is disabled. Re-enabling restores portal access; review service access separately.':'Disabling signs this person out, revokes Live TV, and disables Jellyfin. Their history is kept. Plex sharing is managed separately.'}}</p><p v-if="selected.id===state.user.id" class="small muted">You cannot disable your own account.</p></div><CindorButton v-if="selected.disabled" variant="ghost" class="button" :disabled="busy" @click="action('enable')">Re-enable account</CindorButton><CindorButton v-else-if="!confirmDisable" variant="ghost" class="button danger" :disabled="busy||selected.id===state.user.id" @click="confirmDisable=true">Disable account…</CindorButton><div v-if="confirmDisable" class="notice disable-confirmation" role="group" aria-label="Confirm account disable"><p>Disable {{selected.name}} and revoke their managed access?</p><div class="actions"><CindorButton variant="ghost" class="button danger" :disabled="busy" @click="action('disable')">Confirm disable</CindorButton><CindorButton variant="ghost" class="text-button" :disabled="busy" @click="confirmDisable=false">Cancel</CindorButton></div></div></section>
  </section>
  <section class="panel"><h2>Background work</h2><p v-if="!overview.jobs.length" class="muted">Nothing waiting.</p><ul class="plain-list"><li v-for="job in overview.jobs" :key="job.id"><span>{{job.kind}}<small>{{job.error||'Queued'}} · {{job.attempts}} attempts</small></span><NuxtLink v-if="job.kind==='alert-email'" class="inline-link" to="/admin/alerts">View alerts</NuxtLink><CindorButton variant="ghost" v-else class="text-button" :disabled="busy" @click="run(()=>send('admin/jobs/retry',{id:job.id}))">Retry</CindorButton></li></ul></section>
  <section class="panel"><h2>Recent activity</h2><div class="table-scroll"><table><thead><tr><th>When</th><th>Action</th><th>Target</th><th>Actor</th></tr></thead><tbody><tr v-for="event in overview.audit" :key="event.id"><td>{{date(event.created)}}</td><td>{{event.action}}</td><td>{{event.target}}</td><td>{{overview.users.find((u:any)=>u.id===event.actor)?.name||event.actor}}</td></tr></tbody></table></div><p v-if="!overview.audit.length" class="muted">No activity yet.</p></section>
</main></template>

<style scoped>
.person-detail{margin-top:24px}.person-detail .section-heading{align-items:flex-start;gap:20px}.person-detail .eyebrow{margin-bottom:8px}.person-detail h2{margin-bottom:8px}.person-detail h3{margin:0 0 10px;font-size:18px}.person-access-grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(220px,1fr);gap:32px;margin-top:28px}.person-section{min-width:0}.person-section p{line-height:1.7}.person-section .actions{flex-wrap:wrap;align-items:center;gap:12px;margin-top:18px}.person-library-picker{border:1px solid var(--border);border-radius:10px;padding:18px;margin:20px 0 12px}.person-library-picker legend{font-size:13px;color:var(--muted);padding:0 6px}.person-library-options{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:18px}.person-library-options .check-label{margin:0;overflow-wrap:anywhere}.person-account,.person-recovery{border-top:1px solid var(--border);padding-top:24px;margin-top:28px}.person-account{display:flex;gap:24px;align-items:flex-start;flex-wrap:wrap}.person-account>div:first-child{flex:1;min-width:220px}.person-account>.button{flex-shrink:0}.disable-confirmation{width:100%}.person-recovery form{max-width:640px}@media(max-width:700px){.person-access-grid{grid-template-columns:1fr;gap:24px}.person-access-grid>.person-section+section{border-top:1px solid var(--border);padding-top:24px}.person-detail .section-heading{flex-wrap:wrap}.person-library-options{grid-template-columns:1fr}}
</style>
